    def unload(self):
        # Remove the menu from the Plugins menu
        # We need to remove the menu by its name
        plugins_menu = self.iface.pluginMenu()
        for action in plugins_menu.actions():
            if action.text() == "&GeoFlow-SPH":
                plugins_menu.removeAction(action)
                break
        
        # Remove toolbar icon
        self.iface.removeToolBarIcon(self.action)
        
        # Clean up algorithm actions
        self.algorithm_actions.clear()

    # Methods to run the algorithms using QGIS Processing framework
    def run_dem_to_top(self):
        """Run DEM to TOP algorithm"""
        from qgis import processing
        from qgis.core import QgsProcessingAlgorithm
        
        alg = DemToTop()
        # Create and show the algorithm dialog
        processing.execAlgorithmDialog(alg)

    def run_points_to_pts(self):
        """Run Points to PTS algorithm"""
        from qgis import processing
        
        alg = PointsToPts()
        processing.execAlgorithmDialog(alg)

    def run_res_to_netcdf(self):
        """Run RES to netCDF algorithm"""
        from qgis import processing
        
        alg = ResToNetcdf()
        processing.execAlgorithmDialog(alg)

    def run_sph_simple(self):
        """Run SPH Simple Mode algorithm"""
        from qgis import processing
        
        alg = SphSimpleMode()
        processing.execAlgorithmDialog(alg)

    def run(self):
        """Run the Data-Master dialog"""
        if not self.dlg:
            self.dlg = GeoFlow(iface=self.iface)
        self.dlg.show()
        
