    def toggle_text_input(self):
        # Enable or disable plain_text_input2 based on combo box selection
        combo_selection_inj = self.comboBox_inj.currentText()                    #SMT
        combo_selection_model = self.comboBox_model.currentText()                    #SMT
         # Enable or disable plain_text_input2 based on combo box selection
        if combo_selection_model == "Deterministic Propagation Model":
            self.plainTextEdit_rf.setDisabled(True)
            #self.plainTextEdit_rf.clear()  # Clear text when disabling
        else:
            self.plainTextEdit_rf.setEnabled(True)
            self.plainTextEdit_rf.setPlainText("0")  

        if self.checkBox_c34_hrelsat.isChecked():
            self.plainTextEdit_c19_sr.setEnabled(True)
            self.plainTextEdit_c19_sr.setText("0")
