    def show_error_inj(self):
            """Displays error messages based on the comboBox selection."""
            error_messages = {
                    "No Injection": "There is no need to define anything.",
                    "Normal Injection": "This feature is not available in the public section of the interface.",
                    "Riemann Injection": "This feature is not available in the public section of the interface."
                    }
            QMessageBox.warning(self.tab_1, "Error", error_messages.get(self.comboBox_inj.currentText(), "Unknown selection."))
            return  # This stops further execution
            print("This won't execute") # This code will never run
           
    def show_error_sp(self):
        combo_selection_sp = self.comboBox_sp.currentText()                    #SMT 
