         # Create QSettings instance to handle saving data
         settings = QtCore.QSettings("MyApp4", "TextStorage4")  # Add this line to create settings

          # Optionally save the current text values before clearing them
         if hasattr(self, 'second_window'):
             self.second_window.save_text()  # This ensures the second window's data is saved

            # Clear the saved values (optional, based on your needs)
         for key in ["savedText", "savedText2", "savedText3", "savedText4", "savedText5"]:
             settings.setValue(key, None)  # Clear the saved data

         event.accept()  # Accept the event and close the window
 




  